TLM.f("Sancti/09-03",{"officium":"S. Pii X Papæ Confessoris","rule":["vide C4b","Gloria","CredoDA"],"ruleInherited":["Prefatio=Apostolis"],"fallback":"Commune/C4b","sections":{"Introitus":[{"k":"ref","la":"Ps 88:20-22"},{"k":"text","la":"Extuli eléctum de pópulo, óleo sancto meo unxi eum: ut manus mea sit semper cum eo, et brácchium meum confírmet eum."},{"k":"ref","la":"Ps. 88:2"},{"k":"text","la":"Grátias Dómini in ætérnum cantábo: per omnes generatiónes annuntiábo fidelitátem tuam ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Extuli eléctum de pópulo, óleo sancto meo unxi eum: ut manus mea sit semper cum eo, et brácchium meum confírmet eum."}],"Oratio":[{"k":"text","la":"Deus, qui ad tuéndam cathólicam fidem, et univérsa in Christo instauránda sanctum Pium, Summum Pontíficem, cælésti sapiéntia et apostólica fortitúdine replevísti: concéde propítius; ut, ejus institúta et exémpla sectántes, præmia consequámur ætérna."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Lectio prima Sancti Pauli apóstoli ad Thessalonicénses"},{"k":"ref","la":"1 Thess 2:2-8"},{"k":"text","la":"Fratres: Fidúciam habúimus in Deo nostro, loqui ad vos Evangélium Dei in multa sollicitúdine. Exhortátio enim nostra non de erróre, neque de immundítia, neque in dolo, sed sicut probáti sumus a Deo ut crederétur nobis Evangélium: ita lóquimur non quasi homínibus placéntes, sed Deo, qui probat corda nostra. Neque enim aliquándo fúimus in sermóne adulatiónis, sicut scitis: neque in occasióne avarítiæ: Deus testis est: nec quæréntes ab homínibus glóriam, neque a vobis, neque ab áliis. Cum possémus vobis óneri esse ut Christi apóstoli: sed facti sumus párvuli in médio vestrum, tamquam si nutrix fóveat fílios suos. Ita desiderántes vos, cúpide volebámus trádere vobis non solum Evangélium Dei, sed étiam ánimas nostras: quóniam caríssimi nobis facti estis."}],"Graduale":[{"k":"ref","la":"Ps 39:10-11"},{"k":"text","la":"Annuntiávi justítiam tuam in cœtu magno; ecce lábia mea non cohíbui: Dómine, tu nosti."},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo; fidelitátem tuam et auxílium tuum narrávi. Allelúia, allelúia.","mark":"V"},{"k":"ref","la":"Ps 22:5-6"},{"k":"text","la":"Paras mihi mensam, inúngis óleo caput meum, calix meus ubérrimus est. Allelúia."}],"GradualeP":[{"k":"text","la":"Alleluia, alleluia."},{"k":"ref","la":"Ps 22:5-6"},{"k":"text","la":"Paras mihi mensam, inúngis óleo caput meum, calix meus ubérrimus est. Allelúia."},{"k":"ref","la":"Ps 25:8"},{"k":"text","la":"Dómine, díligo habitáculum domus tuæ et locum tabernáculi glóriæ tuæ. Allelúia.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 131:16-18"},{"k":"text","la":"Sacerdótes ejus índuam salúte, et sancti ejus exsultántes exsultábunt."},{"k":"text","la":"Illic David suscitábo cornu, parábo lucérnam uncto meo.","mark":"V"},{"k":"text","la":"Inimícos ejus índuam confusióne, super ipsum autem fulgébit diadéma meum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia Sancti evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 21:15-17"},{"k":"text","la":"In illo témpore, dicit Jesus Simóni Petro: Simon Joánnis, díligis me plus his? Dicit ei: Etiam Dómine, tu scis quia amo te. Dicit ei: Pasce agnos meos. Dicit ei íterum: Simon Joánnis, díligis me? Ait illi: Etiam Dómine, tu scis quia amo te. Dicit ei: Pasce agnos meos. Dicit ei tértio: Simon Joánnis, amas me? Contristátus est Petrus, quia dixit ei tértio: Amas me? et dixit ei: Dómine, tu ómnia nosti, tu scis quia amo te. Dixit ei: Pasce oves meas."}],"Offertorium":[{"k":"ref","la":"Ps 33:12"},{"k":"text","la":"Veníte, fílii; audíte me: timórem Dómini docébo vos."}],"Secreta":[{"k":"text","la":"Oblatiónibus nostris, quǽsumus, Dómine, benígne suscéptis, da nobis, ut hæc divína mystéria, sancto Pio Summo Pontífice intercedénte, sincéris tractémus obséquiis et fidéli mente sumámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 6:56-57"},{"k":"text","la":"Caro enim mea vere est cibus: et sanguis meus, vere est potus; qui mandúcat meam carnem et bibit meum sánguinem, in me manet, et ego in illo."}],"Postcommunio":[{"k":"text","la":"Mensæ cæléstis virtúte refécti, quǽsumus, Dómine Deus noster: ut, interveniénte sancto Pio Summo Pontífice; fortes efficiámur in fide, et in tua simus caritáte concórdes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3b974529a05616c3":{"t":"Ps 88, 20-22, Ps 88, 2\n(Ps 88, 20-22) Uzdigao sam odabranika iz naroda, pomazao sam ga svetim uljem svojim. Moja će ga ruka štititi i moja mišica jačati. (Ps 88, 2) O milostima Gospodnjim uvijek ću pjevati, kroz sva pokoljenja naviještat ću vjernost tvoju ustima svojim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 88, 20-22) Uzdigao sam odabranika iz naroda, pomazao sam ga svetim uljem svojim. Moja će ga ruka štititi i moja mišica jačati."},"8b66a382b940fcb5":{"t":"<i>Pomolimo se</i>.\nBože, koji si na obranu katoličke vjere i za obnovu svega u Kristu napunio svetoga Pija papu nebeskom mudrošću i apostolskom hrabrošću, daj milostivo, da nasljedujući njegove uredbe i primjere postignemo vječnu nagradu.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7dd179ea8488a981":{"t":"1 Sol 2, 2-8\nČitanje Poslanice bl. Pavla apostola Solunjanima. Braćo, pouzdali smo se u svojega Boga da vam propovijedamo Božje evanđelje usred velike borbe. Naše se propovijedanje ne oslanja na prijevari ni nečistoj nakani, ni lukavštini, nego kao što nas je Bog pronašao dostojnima, te nam povjerio evanđelje,, propovijedamo ne tražeći da se svidimo ljudima, nego Bogu koji pozna naše nakane. Naše propovijedanje, kao što znate, nikada nije bilo laskavo ni pod izlikom lakomosti, čemu je svjedok sam Bog, niti smo tražili slave od ljudi ni od vas ni od drugih. Mogli smo kao Kristovi apostoli pred vama nastupati s vlašću, ali smo s vama bili blagi kao majka kada njeguje svoju djecu. Tako smo vas ljubili, da smo vruće željeli da vam predamo ne samo evanđelje nego i svoj vlastiti život: tako ste nam omiljeli!","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.98)"},"b52c6f457114fb8b":{"t":"Ps 39, 10-11\nNaviještao sam pravdu tvoju na velikom zboru, svoja usta nisam suzdržavao. Gospodine ti znadeš. Pravdu tvoju nisam sakrio u srcu svome, pripovijedao sam o tvojoj vjernosti i pomoći.\n\nPs 22, 5-6\n<i>Aleluja</i>, <i>aleluja</i>.\nProstireš stol preda mnom, uljem mi mažeš glavu, čaša je moja prepuna. <i>Aleluja</i>."},"3d935769853b4627":{"t":"Iv 21, 15-17\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus Šimunu Petru: Šimune Ivanov, ljubiš li me više nego ovi? Reče mu: Da, Gospodine, ti znaš da te ljubim. Reče mu: Pasi jaganjče moje! Reče mu opet drugi put: Šimune Ivanov, ljubiš li me? Odgovori mu: Da, Gospodine, ti znaš da te ljubim. Reče mu: Pasi jaganjče moje! Reče mu treći put: Šimune Ivanov, ljubiš li me? Ožalosti se Petar što ga po treći put pita: Ljubiš li me? I odgovori mu: Gospodine, ti sve znaš, ti znaš da te ljubim. Reče mu Isus: Pasi ovce moje!"},"a3dbd4092e2a688f":{"t":"Ps 33, 12\nDođite, sinovi, čujte me! Naučit ću vas strahu Gospodnjemu.","kn":"(Ps. 233, 12). Dođite, sinci, čujte me, učit ću vas strahu Gospodnjem.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"119994b78646b1b9":{"t":"Naše prinose dobrostivo primi, molimo, Gospodine, i daj nam da ove božanske tajne po zagovoru Svetoga pape Pija obavljamo iskrenom privrženošću i primamo vjernom dušom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"9862df39a9332829":{"t":"Iv 6, 56-57\nMoje je tijelo zaista jelo i moja je krv zaista piće. Tko jede moje tijelo i pije moju krv, ostaje u meni i ja u njemu.","v":"∅ → enim","kn":"(Iv. 6, 57). Tko blaguje tijelo moje i pije krv moju, u meni ostaje i ja u njemu, veli Gospodin.","knRef":"Kniewald 1942, str. 140–141 (snimka 71) (OCR)"},"29901a18e34390d8":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni jakošću nebeske gozbe molimo, Gospodine Bože naš, da po zagovoru svetoga pape Pija ojačamo u vjeri i budemo složni u tvojoj ljubavi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
